#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);root<-if(length(args))normalizePath(args[[1]])else normalizePath(".")
.libPaths(c(file.path(root,"project","Rlib-4.5"),file.path(root,"renv","library","macos","R-4.5","aarch64-apple-darwin20"),.libPaths()))
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork);library(scales)})
net<-file.path(root,"project","results","network");rob<-file.path(root,"project","results","virtual_perturbation");out<-file.path(root,"project","results","figures")
pal<-c(other="#999999",AD_only="#0072B2",URE_only="#D55E00",intersection="#009E73")
theme_pub<-theme_classic(base_size=7.2)+theme(plot.title=element_text(face="bold",size=8.5),plot.subtitle=element_text(size=6.3),axis.title=element_text(face="bold"),legend.title=element_text(face="bold"),plot.margin=margin(5,7,5,5))
save_page<-function(p,stem,h){ggsave(file.path(out,paste0(stem,".pdf")),p,width=183,height=h,units="mm",device="pdf",useDingbats=FALSE,bg="white");ggsave(file.path(out,paste0(stem,".png")),p,width=183,height=h,units="mm",dpi=600,bg="white")}
wrap<-function(x,w=42)vapply(x,function(z)paste(strwrap(z,width=w),collapse="\n"),character(1))
annotate_module<-function(g){m<-rep("other",length(g));m[g%in%c("FBN1","ACTA2","COL3A1","COL5A1","EFEMP2","EMILIN1","ENPP1","LOX","MFAP5","MYLK","PLOD3","PRKG1","SMAD2","SMAD3","TGFB2","TGFB3","TGFBR1","TGFBR2","THBS2","THSD4")]<-"AD_only";m[g%in%c("ELN","COL1A1","MMP1","MMP2","MMP9","TIMP1","BGN","MGP","RUNX2","SPP1","BMP2","IBSP","NOX4","NFKB1","NFE2L2","ACE","AGTR1","AGT","TGFB1","ENG","BMP4")]<-"URE_only";m[g%in%c("COL3A1","LOX","SMAD3","TGFBR1","TGFBR2")]<-"intersection";m}

# S6: database coverage, descriptive topology and enrichment.
coverage<-data.table(status=factor(c("Connected","Mapped, isolated","Unmapped"),levels=c("Connected","Mapped, isolated","Unmapped")),count=c(511L,67L,1L))
p1<-ggplot(coverage,aes(status,count,fill=status))+geom_col(width=.68,colour="black",linewidth=.25)+geom_text(aes(label=count),vjust=-.35,size=2.5)+scale_fill_manual(values=c("Connected"="#0072B2","Mapped, isolated"="#E69F00","Unmapped"="#999999"),guide="none")+scale_y_continuous(limits=c(0,550),expand=expansion(mult=c(0,.02)))+labs(tag="A",title="STRING coverage",subtitle="Frozen input: n=579",x=NULL,y="Input genes (n)")+theme_pub+theme(axis.text.x=element_text(angle=25,hjust=1))
hub<-fread(file.path(net,"hub_genes.csv"));hub[,module:=annotate_module(gene)];topd<-hub[order(-degree,gene)][1:15];topd[,gene:=factor(gene,levels=rev(gene))]
p2<-ggplot(topd,aes(gene,degree,fill=module))+geom_col(width=.72,colour="black",linewidth=.15)+coord_flip()+scale_fill_manual(values=pal,breaks=c("intersection","AD_only","URE_only","other"),labels=c("AD–URE overlap","AD-labelled","Uremic mechanism","Other"))+labs(tag="B",title="Degree-ranked nodes",subtitle="Connectivity is descriptive, not causal",x=NULL,y="Degree",fill="Seed annotation")+theme_pub+theme(legend.position="bottom")
enr<-fread(file.path(net,"enrichment_table.csv"))[order(p.adjust,-Count)][1:12];enr[,Description:=factor(wrap(Description),levels=rev(wrap(Description)))];enr[,neglogq:=-log10(pmax(p.adjust,.Machine$double.xmin))]
p3<-ggplot(enr,aes(FoldEnrichment,Description,size=Count,colour=neglogq))+geom_point(alpha=.9)+scale_colour_viridis_c(option="C")+scale_size_continuous(range=c(2.2,6))+labs(tag="C",title="GO Biological Process enrichment",subtitle="Explicit org.Hs.eg.db Entrez universe",x="Fold enrichment",y=NULL,colour=expression(-log[10](BH~adjusted~P)),size="Gene count")+theme_pub
s6<-(p1|p2)/p3+plot_annotation(title="STRING network coverage, descriptive topology and functional enrichment",subtitle="Database organization of the frozen 579-gene union does not identify causal drivers or therapeutic targets",theme=theme(plot.title=element_text(face="bold",size=10),plot.subtitle=element_text(size=7)))+plot_layout(heights=c(.9,1.15))
save_page(s6,"Supplementary_Figure_S6_network_coverage_topology_enrichment",170)
fwrite(coverage,file.path(out,"Supplementary_Figure_S6_source_data_A_coverage.tsv"),sep="\t");fwrite(topd,file.path(out,"Supplementary_Figure_S6_source_data_B_degree.tsv"),sep="\t");fwrite(enr,file.path(out,"Supplementary_Figure_S6_source_data_C_enrichment.tsv"),sep="\t")

# S7: robustness and seed proximity; no biological-intervention terminology.
bet<-fread(file.path(rob,"betweenness.csv"));topb<-bet[order(-betweenness_normalized,gene)][1:15];topb[,gene:=factor(gene,levels=rev(gene))]
p4<-ggplot(topb,aes(gene,betweenness_normalized,fill=module))+geom_col(width=.72,colour="black",linewidth=.15)+coord_flip()+scale_fill_manual(values=pal,breaks=c("intersection","AD_only","URE_only","other"),labels=c("AD–URE overlap","AD-labelled","Uremic mechanism","Other"))+labs(tag="A",title="Betweenness-ranked nodes",subtitle="Normalized unweighted Brandes betweenness",x=NULL,y="Normalized betweenness",fill="Seed annotation")+theme_pub+theme(legend.position="bottom")
ko<-fread(file.path(rob,"ko_fragmentation.csv"));ko[,label:=factor(c("Baseline","COL3A1","LOX","SMAD3","TGFBR1","TGFBR2","All five"),levels=c("Baseline","COL3A1","LOX","SMAD3","TGFBR1","TGFBR2","All five"))]
p5<-ggplot(ko,aes(label,largest_fraction))+geom_col(width=.68,fill="#56B4E9",colour="black",linewidth=.25)+scale_y_continuous(limits=c(0,1),breaks=seq(0,1,.2),labels=percent_format(accuracy=1),expand=c(0,0))+labs(tag="B",title="Largest component after node removal",subtitle="Six components in every condition; graph sensitivity only",x=NULL,y="Largest-component fraction")+theme_pub+theme(axis.text.x=element_text(angle=35,hjust=1))
pairs<-fread(file.path(rob,"ure_ad_pair_distances.csv"));dist<-pairs[,.N,by=distance][order(distance)]
p6<-ggplot(dist,aes(factor(distance),N))+geom_col(width=.68,fill="#E69F00",colour="black",linewidth=.25)+geom_text(aes(label=N),vjust=-.3,size=2.5)+scale_y_continuous(limits=c(0,max(dist$N)*1.12),expand=c(0,0))+labs(tag="C",title="URE-only to AD-only seed distances",subtitle="All 315 connected seed pairs",x="Unweighted shortest-path distance",y="Gene pairs (n)")+theme_pub
cov<-fread(file.path(rob,"path_coverage.csv"));cov[,gene:=factor(gene,levels=gene[order(percentage)])]
p7<-ggplot(cov,aes(gene,percentage))+geom_col(width=.68,fill="#009E73",colour="black",linewidth=.25)+coord_flip()+geom_text(aes(label=sprintf("%.1f%%",percentage)),hjust=-.15,size=2.5)+scale_y_continuous(limits=c(0,max(cov$percentage)*1.2),expand=c(0,0))+labs(tag="D",title="Shortest paths via overlap gene",subtitle="At least one shortest path; not causal mediation",x=NULL,y="URE-AD seed pairs (%)")+theme_pub
s7<-(p4|p5)/(p6|p7)+plot_annotation(title="Frozen-network robustness and URE-AD seed proximity",subtitle="Analyses use an undirected STRING association graph and do not model intervention, causality or treatment efficacy",theme=theme(plot.title=element_text(face="bold",size=10),plot.subtitle=element_text(size=7)))
save_page(s7,"Supplementary_Figure_S7_network_robustness_seed_proximity",160)
fwrite(topb,file.path(out,"Supplementary_Figure_S7_source_data_A_betweenness.tsv"),sep="\t");fwrite(ko,file.path(out,"Supplementary_Figure_S7_source_data_B_node_removal.tsv"),sep="\t");fwrite(pairs,file.path(out,"Supplementary_Figure_S7_source_data_C_pair_distances.tsv"),sep="\t");fwrite(cov,file.path(out,"Supplementary_Figure_S7_source_data_D_path_coverage.tsv"),sep="\t")
idx<-data.table(figure=c("S6","S7"),visual_file=c("Supplementary_Figure_S6_network_coverage_topology_enrichment.pdf","Supplementary_Figure_S7_network_robustness_seed_proximity.pdf"),claim_ids=c("C6","C7-C9"),boundary=c("Descriptive database organization only","Graph robustness and proximity are not biological intervention"));fwrite(idx,file.path(out,"Supplementary_Figures_S6_S7_source_data.tsv"),sep="\t")
writeLines(capture.output(sessionInfo()),file.path(out,"Supplementary_Figures_S6_S7_sessionInfo.txt"));cat("SUPPLEMENTARY_FIGURES_S6_S7_COMPLETE\n")
